{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가. 적절한(부적절한) 소화제",
      "start": "p2:L22",
      "end": "p2:L23"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "start": "p2:L24",
      "end": "p2:L37"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다. 화재진압시 착용할 보호구 및 예방조치",
      "start": "p2:L38",
      "end": "p2:L51"
    }
  ],
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "reason": "코드없음"
    ,
      "statements": [
        {
          "key": "극인화성 가스",
          "value": "압축가스 포함 ; 가열하면 폭발할 수 있음"
        ,
          "refs": [
            "1"
          ]
        ,
          "line": "p2:L24"
        },
        {
          "value": "격렬하게 중합반응하여 화재와 폭발을 일으킬 수 있음",
          "line": "p2:L26"
        },
        {
          "value": "가열시 용기가 폭발할 수 있음",
          "line": "p2:L27"
        },
        {
          "value": "공기와 폭발성 혼합물을 형성함",
          "line": "p2:L28"
        },
        {
          "value": "극인화성",
          "line": "p2:L29"
        },
        {
          "value": "수소(UN No. 1049) / 중수소(UN No. 1957) / 압축수소메탄혼합물(UN No. 2034)은 화염이 눈에 보이지 않음",
          "line": "p2:L30"
        },
        {
          "value": "열, 스파크, 화염에 의해 쉽게 점화함",
          "line": "p2:L32"
        },
        {
          "value": "증기는 점화원까지 이동하여 역화 (flash back)할 수 있음",
          "line": "p2:L33"
        },
        {
          "value": "화재에 노출된 실린더는 가연성 가스를 방출할 수 있음",
          "line": "p2:L34"
        },
        {
          "value": "일부 물질은 고농도로 흡입시 자극적일 수 있음",
          "line": "p2:L35"
        },
        {
          "value": "증기는 자각 없이 현기증 또는 질식을 유발할 수 있음",
          "line": "p2:L36"
        },
        {
          "value": "화재시 자극성, 부식성, 독성 가스를 발생할 수 있음",
          "line": "p2:L37"
        }
      ]
    ,
      "suggested_code": "S5_SPECIFIC"
    ,
      "line": "p2:L24"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "다. 화재진압시 착용할 보호구 및 예방조치",
      "reason": "코드없음"
    ,
      "statements": [
        {
          "value": "누출성 가스 화재 시 누출을 안전하게 막을 수 없다면 불을 끄려하지 마시오",
          "line": "p2:L38"
        },
        {
          "value": "안전하게 처리하는 것이 가능하면 모든 점화원을 제거하시오",
          "line": "p2:L39"
        },
        {
          "value": "구조자는 적절한 보호구를 착용하시오.",
          "line": "p2:L40"
        },
        {
          "value": "지역을 벗어나 안전거리를 유지하여 소화하시오",
          "line": "p2:L41"
        },
        {
          "value": "파손된 실린더는 날아오를 수 있으니 주의하시오",
          "line": "p2:L42"
        },
        {
          "value": "누출이 중지되지 않는다면 누출가스화재를 소화하지 마시오",
          "line": "p2:L43"
        },
        {
          "value": "위험하지 않다면 화재지역에서 용기를 옮기시오",
          "line": "p2:L44"
        },
        {
          "value": "탱크 화재시 결빙될 수 있으므로 노출원 또는 안전장치에 직접주수하지 마시오",
          "line": "p2:L45"
        },
        {
          "value": "탱크 화재시 최대거리에서 소화하거나 무인 소화장비를 이용하시오",
          "line": "p2:L46"
        },
        {
          "value": "탱크 화재시 소화가 진화된 후에도 다량의 물로 용기를 식히시오",
          "line": "p2:L47"
        },
        {
          "value": "탱크 화재시 압력 방출장치에서 고음이 있거나 탱크가 변색할 경우 즉시 물러나시오",
          "line": "p2:L48"
        },
        {
          "value": "탱크 화재시 화염에 휩싸인 탱크에서 물러나시오",
          "line": "p2:L49"
        },
        {
          "value": "탱크 화재시 대규모 화재의 경우 무인 소화장비를 이용하고 불가능하다면 물러나 타게 놔두시오",
          "line": "p2:L50"
        }
      ]
    ,
      "suggested_code": "S5_FIREFIGHT"
    ,
      "line": "p2:L38"
    }
  ]
}

